function bindSubmit(form,handler){form.onsubmit=async event=>{event.preventDefault();if(busyForms.has(form))return;busyForms.add(form);dialogBusy++;const buttons=[...form.querySelectorAll('[type=submit]')];for(const button of buttons)button.disabled=true;try{await handler(event);}finally{busyForms.delete(form);dialogBusy--;for(const button of buttons)button.disabled=false;}};}
function clearReceiver(){stopCallAlerts();session.reset();cleanupPlayer();state={...state,mode:'offline',channels:[],selected:null,timers:[],settings:{},capabilities:[],receiver:null,snr:null,quality:null,strength:null};stopBeep();stopGyro();clearInterval(signalTimer);}
async function api(path,method='GET',body,connection=null){
 const base=connection?.bridge??bridge,secret=connection?.token??token;
 if(!base)throw Error('Connect the local bridge first.');
 const epoch=session.epoch;
 const request=async signal=>{
  const response=await fetch(base+path,{method,headers:{Authorization:'Bearer '+secret,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal});
  let data;try{data=await response.json();}catch{throw Error('The bridge returned invalid JSON.');}
  if(!Core.object(data))throw Error('The bridge returned an invalid response.');
  if(!response.ok){
   if(!connection&&epoch===session.epoch&&[401,403,409].includes(response.status)){clearReceiver();if(response.status!==409)bridgeConnected=false;render();}
   throw Error(data.error||'Receiver request failed.');
  }
  return data;
 };
 try{return await (connection?new Core.Session():session).run(request,path==='/api/channels'?55000:path==='/api/discover'?30000:9000);}
 catch(error){
  if(!connection&&epoch!==session.epoch)throw Error('Connection changed. Refresh before trying again.');
  if(error.name==='AbortError'||error instanceof TypeError){if(!connection){clearReceiver();bridgeConnected=false;render();}throw Error('Bridge unavailable or request timed out. Check the local connection.');}
  throw error;
 }
}
async function command(cap,path,body){
 if(!has(cap))throw Error('A connected receiver supporting '+cap+' is required.');
 if(commandBusy)throw Error('A receiver command is still in progress. Please wait.');
 commandBusy=true;
 try{const result=await api(path,'POST',body);if(path==='/api/stream'){Core.streamUrl(result.url,bridge);}else if(result.ok!==true)throw Error('Receiver did not acknowledge this operation.');return result;}
 finally{commandBusy=false;}
}
function stopRemoteStream(current){if(!current?.id)return Promise.resolve();return fetch(current.base+'/api/satip/stop',{method:'POST',headers:{Authorization:'Bearer '+current.token,'Content-Type':'application/json'},body:JSON.stringify({streamId:current.id}),keepalive:true,signal:AbortSignal.timeout(9000)}).catch(()=>{});}
async function watchResponse(data,connection,isCurrent){const ticket={id:data.streamId,...connection};if(!isCurrent()){await stopRemoteStream(ticket);return;}try{await watchUrl(data.url,connection.base,data.streamId,connection);}catch(error){await stopRemoteStream(ticket);throw error;}}
function cleanupPlayer(){if(activeStream){const current=activeStream;activeStream=null;stopStreamPromise=stopRemoteStream(current);}const video=$('#streamPlayer');if(video){video.onplaying=null;video.onerror=null;video.pause();video.removeAttribute('src');video.load();}return stopStreamPromise;}
