function remote(){if(!has('remote'))return head('Remote control','Control a connected receiver.')+unavailable('remote');return head('Remote control','The familiar controls, with a little more freedom.')+`<div class="remote-layout"><div class="panel pad"><div class="remote"><div class="remote-top"><span class="remote-label">ALEN / REMOTE</span><button class="icon-btn power" data-action="remote-key" data-key="POWER" aria-label="Power">${icon('power')}</button></div><div class="remote-grid">${['1','2','3','4','5','6','7','8','9','INFO','0','MUTE'].map(k=>`<button data-action="remote-key" data-key="${k}">${k}</button>`).join('')}</div><div class="dpad">${[['UP','up'],['LEFT','left'],['OK',''],['RIGHT','right'],['DOWN','down']].map(([k,i])=>`<button data-action="remote-key" data-key="${k}" aria-label="${k}">${i?icon(i):'OK'}</button>`).join('')}</div><div class="remote-bottom">${['MENU','BACK','EXIT'].map(k=>`<button data-action="remote-key" data-key="${k}">${k}</button>`).join('')}</div><div class="remote-grid">${['VOL+','EPG','CH+','VOL-','FAV','CH-'].map(k=>`<button data-action="remote-key" data-key="${k}">${k}</button>`).join('')}</div><div class="color-buttons">${['RED','GREEN','YELLOW','BLUE'].map((k,i)=>`<button aria-label="${k}" data-action="remote-key" data-key="${k}" style="background:${['#d67772','#9ace75','#ddc366','#6f9dbd'][i]}"></button>`).join('')}</div></div></div><div><div class="panel pad"><div class="flex"><h2 class="grow">Touchpad</h2><span class="badge">Swipe + tap</span></div><p>Swipe to move. Tap to select. Arrow keys and Enter work here too.</p><div id="touchpad" class="touchpad" tabindex="0" role="application" aria-label="Remote touchpad. Use arrows to move and Enter to select."><div>${icon('remote')}<p>Swipe anywhere</p><small>Tap for OK</small></div></div><div class="keylog" id="keylog">Ready</div></div><div class="panel pad" style="margin-top:20px"><h2>Motion control</h2><p>Tilt your phone to navigate. Requires motion permission and a compatible phone browser.</p>${btn('gyro','Enable motion','remote','ghost','style="margin-top:15px"')}<p id="gyroState" class="hint">Off</p></div><p class="hint" style="margin-top:18px">Power-on depends on the receiver remaining reachable in standby.</p></div></div>`;}

