async function autoBootstrap(){
 if(bootstrapPromise)return bootstrapPromise;
 if(location.protocol!=='http:'||!['localhost','127.0.0.1'].includes(location.hostname))return false;
 const epoch=pairingSession.epoch;
 const job=pairingSession.run(async signal=>{
  const response=await fetch(location.origin+'/api/bootstrap',{method:'POST',headers:{'X-Alen-Bootstrap':'1'},signal});
  if(!response.ok)throw Error('Local pairing unavailable.');
  const data=await response.json();
  if(data.protocol!=='alen-stb-bridge-v1'||data.automatic!==true||typeof data.token!=='string'||data.token.length<16||data.bridge!==location.origin)throw Error('Invalid local pairing response.');
  return data;
 },3000).then(data=>{
  if(epoch!==pairingSession.epoch)return false;
  if(token&&token!==data.token)clearReceiver();
  bridge=location.origin;token=data.token;bridgeConnected=true;automaticBridge=true;
  if(data.target&&typeof data.target.host==='string'&&Number.isInteger(data.target.port))receiverTarget=data.target;
  nav();return true;
 }).catch(()=>{
  if(epoch===pairingSession.epoch&&automaticBridge&&bridge===location.origin){clearReceiver();bridgeConnected=false;automaticBridge=false;token='';render();}
  return false;
 }).finally(()=>{if(bootstrapPromise===job)bootstrapPromise=null;});
 bootstrapPromise=job;return job;
}
function connectionFields(){
 const form=$('#connectionForm');if(!form.reportValidity())throw Error('Check the connection fields.');
 const f=new FormData(form);let u;
 try{u=new URL(f.get('url')||bridge);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash||(u.pathname!=='/'&&u.pathname!==''))throw Error();}
 catch{throw Error('Start the local app using Start-Alen-STB.cmd, or set up the bridge under Advanced options.');}
 const secret=String(f.get('token')||token);
 if(!secret)throw Error('Open the local app to connect automatically, or enter a token under Advanced options.');
 const host=String(f.get('host')).trim(),port=Number(f.get('port'));
 if(!Number.isInteger(port)||port<1||port>65535)throw Error('Use a port from 1 to 65535.');
 receiverTarget={host,port};return {host,port,bridge:u.origin,token:secret};
}
function acceptBridge(connection){pairingSession.reset();bootstrapPromise=null;automaticBridge=automaticBridge&&connection.bridge===location.origin;clearReceiver();bridge=connection.bridge;token=connection.token;bridgeConnected=true;render();}
