function stopGyro(){if(gyroHandler){window.removeEventListener('deviceorientation',gyroHandler);gyroHandler=null;}if($('#gyroState'))$('#gyroState').textContent='Off';}
async function gyro(){const target=$('#gyroState');if(!target||!has('remote'))return;if(gyroHandler){stopGyro();return;}if(!window.DeviceOrientationEvent)throw Error('Motion sensors are not available in this browser.');if(typeof DeviceOrientationEvent.requestPermission==='function'){if(await DeviceOrientationEvent.requestPermission()!=='granted')throw Error('Motion permission was not granted.');}if(!target.isConnected||!has('remote'))return;let base=null;gyroHandler=e=>{if(!Number.isFinite(e.beta)||!Number.isFinite(e.gamma))return;if(!base){base={beta:e.beta,gamma:e.gamma};$('#gyroState').textContent='On · tilt left/right or forward/back. Press again to stop.';}const x=e.gamma-base.gamma,y=e.beta-base.beta;if(Date.now()-lastGyro>550&&(Math.abs(x)>18||Math.abs(y)>18)){lastGyro=Date.now();remoteKey(Math.abs(x)>Math.abs(y)?x>0?'RIGHT':'LEFT':y>0?'DOWN':'UP').catch(e=>{stopGyro();toast(e.message);});}};window.addEventListener('deviceorientation',gyroHandler);$('#gyroState').textContent='Waiting for sensor readings… press again to stop.';}
function stopBeep(){audioEpoch++;clearTimeout(beepTimer);beepTimer=null;if($('#beepButton'))$('#beepButton').innerHTML=icon('volume')+'Enable audio guide';}
function beep(){if(!audioCtx||audioCtx.state!=='running')return;if(Date.now()-signalAt>4000||!has('signal')){stopBeep();return;}const n=state.snr;if(Number.isFinite(n)&&n>0){const osc=audioCtx.createOscillator(),g=audioCtx.createGain();osc.frequency.value=500+Math.min(n,25)*40;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.07);osc.connect(g);g.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.08);}beepTimer=setTimeout(beep,Math.max(120,1100-(Number.isFinite(n)?n:0)*45));}
